            //
            aWandererE = aWandererE ^ (((RotL64(aIngress, 20U) + RotL64(aOrbiterD, 60U)) + aOrbiterH) + aTwistWandererUpdateSaltB[((aIndex + 21U)) & S_SALT1]);
            aWandererH = aWandererH + (((RotL64(aCross, 11U) + aOrbiterA) + RotL64(aOrbiterE, 29U)) + RotL64(aCarry, 57U));
