            aOrbiterF = ((aWandererK + RotL64(aScatter, 35U)) + RotL64(aCarry, 37U)) + 0xC32A39851AC0CEB2ULL;
            aOrbiterD = ((aWandererI + RotL64(aPrevious, 57U)) + 0x6BBD574288BE2C7EULL) + aTwistOrbiterAssignSaltA[((aIndex + 5U)) & S_SALT1];
            aOrbiterH = (aWandererG + RotL64(aCross, 46U)) + 0x3886394D647106DDULL;
            aOrbiterJ = (aWandererC + RotL64(aIngress, 5U)) + 0x58A42A0E9A821DA8ULL;
            aOrbiterI = ((aWandererD + RotL64(aPrevious, 27U)) + RotL64(aCarry, 19U)) + 0x172C7CD587CE503DULL;
            aOrbiterA = (((aWandererF + RotL64(aIngress, 11U)) + RotL64(aCarry, 51U)) + 0x88F8B3EBDD729BE3ULL) + aTwistOrbiterAssignSaltE[((aIndex + 28U)) & S_SALT1];
            aOrbiterE = (aWandererH + RotL64(aCross, 21U)) + 0x4389FAB8194E2E44ULL;
            //
            aOrbiterF = (aOrbiterF + aOrbiterD) + 0x9221B4435014BB57ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x8E1CC5BD86179925ULL) ^ aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 6U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x39D8E6FA490E9349ULL), 53U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterF) + 0x143DE3D0A225679BULL) + aTwistOrbiterUpdateSaltF[((aIndex + 18U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterJ) ^ 0xA456667E46582D17ULL;
