            aOrbiterH = (aOrbiterH + aOrbiterA) + 0x89DF78B06F3B6D5DULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterH) ^ 0x0A60F93D88AF70E8ULL) ^ aTwistOrbiterUpdateSaltE[((aIndex + 13U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0x6AD5B0A18E7BF855ULL), 35U);
