            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x3A2AA12CA3E0E8D1ULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterI) ^ 0x4D28730A13AE952BULL;
            aOrbiterE = RotL64((aOrbiterE * 0xB5A5E53443A14557ULL), 13U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterJ) + 0x3EFD84293422A4BAULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterE) ^ 0x9CB4D2689926E0A8ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x49C94F9B5B8E2FABULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterE) + 0xB2D830683B39093BULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterA) ^ 0xDD4D514B9A3D3572ULL;
            aOrbiterF = RotL64((aOrbiterF * 0x6E06F27AE4A64EA5ULL), 47U);
            //
            aIngress = RotL64(aOrbiterD, 19U) ^ aOrbiterJ;
            aIngress = aIngress + (RotL64(aOrbiterF, 11U) ^ aOrbiterI);
