            aCross = (RotL64(aFireLaneC[((S_BLOCK1 - aIndex + 15322U)) & S_BLOCK1], 11U) ^ RotL64(aEarthLaneC[((S_BLOCK1 - aIndex + 12991U)) & S_BLOCK1], 51U));
