            aOrbiterA = ((aOrbiterA ^ aOrbiterG) ^ 0x738A1CA7C46E2B46ULL) ^ aTwistOrbiterUpdateSaltD[((aIndex + 9U)) & S_SALT1];
            aOrbiterA = RotL64((aOrbiterA * 0xE873D9B2B5E15115ULL), 19U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0x547A9693E433F6BCULL;
