            aWandererF = aWandererF ^ (((RotL64(aPrevious, 57U) + aOrbiterD) + RotL64(aOrbiterB, 5U)) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1]);
            aWandererE = aWandererE + (((RotL64(aIngress, 37U) + aOrbiterD) + RotL64(aOrbiterK, 20U)) + RotL64(aCarry, 35U));
