            aOrbiterD = ((aWandererD + RotL64(aCross, 41U)) + 0x95B011EA5651998FULL) + aTwistOrbiterAssignSaltC[(((31U - aIndex) + 9U)) & S_SALT1];
            aOrbiterH = ((aWandererE + RotL64(aIngress, 35U)) + RotL64(aCarry, 13U)) + 0x1059943139D518B0ULL;
            aOrbiterI = (aWandererI + RotL64(aPrevious, 22U)) + 0xD1EB30230843CB9DULL;
            aOrbiterJ = ((aWandererJ + RotL64(aScatter, 47U)) + RotL64(aCarry, 27U)) + 0xD468E73C35E33B46ULL;
            aOrbiterC = ((aWandererK + RotL64(aCross, 57U)) + 0x844AA4B2A09332EFULL) + aTwistOrbiterAssignSaltD[((aIndex + 18U)) & S_SALT1];
            aOrbiterA = ((aWandererA + RotL64(aPrevious, 3U)) + RotL64(aCarry, 43U)) + 0xD18926CD2EB09F2CULL;
            aOrbiterG = (aWandererB + RotL64(aIngress, 29U)) + 0x2042AE7E26A9D290ULL;
            //
            aOrbiterD = (aOrbiterD + aOrbiterH) + 0xE05015EC4EF2AF12ULL;
