            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x29159CA25394C792ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0xA6306DBA034756EFULL) ^ aTwistOrbiterUpdateSaltC[((aIndex + 15U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xF996302BDDBAADE1ULL), 41U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterD) + 0x058BDB6FA32A3DA9ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0x9E4FEB32105DF6F6ULL;
