            aWandererF = aWandererF + (((RotL64(aScatter, 29U) + RotL64(aOrbiterJ, 19U)) + aOrbiterG) + aTwistWandererUpdateSaltD[(((31U - aIndex) + 11U)) & S_SALT1]);
