            aOrbiterD = RotL64((aOrbiterD * 0x13F79030D6466E07ULL), 53U);
            //
            aOrbiterK = ((aOrbiterK + aOrbiterG) + 0xBDA702B5452236D5ULL) + aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 23U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0xEC7F1A029F4722FCULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x480A9AB9B2A648D1ULL), 3U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterC) + 0x1C80DD1AFD8E3701ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterG) ^ 0xBF6745036B46FEFDULL;
            aOrbiterB = RotL64((aOrbiterB * 0x6E19DA4BE69D850FULL), 37U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x0944072799E1B755ULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterF) ^ 0x31B32706C5B69914ULL;
            aOrbiterA = RotL64((aOrbiterA * 0xBBC3438272953A95ULL), 11U);
            //
            aOrbiterH = ((aOrbiterH + aOrbiterK) + 0xB203870B357E4DEAULL) + aTwistOrbiterUpdateSaltE[(((31U - aIndex) + 18U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0x062525A29022F077ULL;
