            //
            aOrbiterE = ((aOrbiterE + aOrbiterI) + 0x74868AA9BF0D180FULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterE) ^ 0x41E755211D90152BULL;
