    std::uint64_t *aTwistOrbiterAssignSaltA = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltA;
    std::uint64_t *aTwistOrbiterAssignSaltB = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltB;
    std::uint64_t *aTwistOrbiterAssignSaltC = pWorkSpace->mDomainBundle.mTwistSalts.mOrbiterAssign.mSaltC;
