            aOrbiterG = RotL64((aOrbiterG * 0x967841A125AB73C1ULL), 47U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterD) + 0xB62035A645DEDCCDULL) + aTwistOrbiterUpdateSaltF[((aIndex + 5U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterB) ^ 0x98DCE4BF73F32661ULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 11U)) & S_SALT1];
