            aOrbiterD = RotL64((aOrbiterD * 0xBBCC70A1D075EAE5ULL), 23U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterA) + 0xBC8EDE94A32A8EADULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterH) ^ 0x49A2A028D15BCC2FULL;
            aOrbiterB = RotL64((aOrbiterB * 0xBF66A4D5B4F58CFDULL), 41U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterF) + 0x54B461676240EDD7ULL;
