            aOrbiterH = RotL64((aOrbiterH * 0xEEAB57C8713C1DEFULL), 35U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x87486D58CE1AE072ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterG) ^ 0x791F8A901E3AC90FULL;
            aOrbiterF = RotL64((aOrbiterF * 0x3628B78B50C710D7ULL), 13U);
            //
            aIngress = RotL64(aOrbiterB, 44U) ^ aOrbiterA;
            aIngress = aIngress + (RotL64(aOrbiterG, 5U) ^ aOrbiterD);
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterE, 37U));
