            //
            aWandererC = aWandererC ^ ((RotL64(aIngress, 27U) + RotL64(aOrbiterD, 19U)) + aOrbiterA);
            aWandererF = aWandererF + (((RotL64(aPrevious, 19U) + RotL64(aOrbiterD, 11U)) + aOrbiterF) + RotL64(aCarry, 53U));
            aWandererD = aWandererD ^ (((RotL64(aCross, 35U) + aOrbiterE) + RotL64(aOrbiterD, 26U)) + aTwistWandererUpdateSaltA[((aIndex + 27U)) & S_SALT1]);
            aWandererI = aWandererI + (((RotL64(aScatter, 11U) + aOrbiterH) + RotL64(aOrbiterE, 53U)) + RotL64(aCarry, 19U));
