            aWandererB = aWandererB + ((RotL64(aCross, 57U) + aOrbiterH) + RotL64(aOrbiterB, 5U));
            aWandererA = aWandererA ^ (((RotL64(aScatter, 44U) + RotL64(aOrbiterA, 47U)) + aOrbiterF) + aTwistWandererUpdateSaltC[(((31U - aIndex) + 23U)) & S_SALT1]);
