            aOrbiterH = ((aWandererF + RotL64(aScatter, 51U)) + 0x3C37B4FEB4D7ED19ULL) + aTwistOrbiterAssignSaltC[((aIndex + 18U)) & S_SALT1];
            //
            aOrbiterC = ((aOrbiterC + aOrbiterB) + 0x908B4A07CC12F05DULL) + aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 28U)) & S_SALT1];
            aOrbiterE = (aOrbiterE ^ aOrbiterC) ^ 0xEF0681DF7C4A0964ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x07194A65353F142DULL), 47U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterI) + 0xF71FCEE6E64D6C72ULL) + aTwistOrbiterUpdateSaltF[((aIndex + 3U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0x08BD4C784F9BBEA1ULL;
