            //
            aOrbiterG = (aOrbiterG + aOrbiterE) + 0x2444F42F80BA3304ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterG) ^ 0xBE67DCB92E204828ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x3B34111B6C9730E7ULL), 35U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterG) + 0xE4BE8AE59DBA82E4ULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterI) ^ 0x673E9B8DA9E03D72ULL;
            aOrbiterB = RotL64((aOrbiterB * 0x2FAC24ED6C48C8D7ULL), 5U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0x51A4F1CCBBAD8CE4ULL) + aTwistOrbiterUpdateSaltB[((aIndex + 29U)) & S_SALT1];
            aOrbiterI = (aOrbiterI ^ aOrbiterE) ^ 0x2B3726BB2AF73043ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x08A4CD88D633A7E7ULL), 27U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0xA4F6FB2280E08757ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0x9B133EE23C907871ULL) ^ aTwistOrbiterUpdateSaltA[(((31U - aIndex) + 5U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x50475DD22EAC4097ULL), 11U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterC) + 0xEE550705F751F6A1ULL;
            aOrbiterG = (aOrbiterG ^ aOrbiterH) ^ 0x80A1F8C342B24212ULL;
            aOrbiterG = RotL64((aOrbiterG * 0x993A99FB8B42D65BULL), 57U);
