            aOrbiterA = (aWandererK + RotL64(aIngress, 19U)) + 0xAEB026C5B754A17CULL;
            aOrbiterH = (((aWandererH + RotL64(aPrevious, 57U)) + RotL64(aCarry, 39U)) + 0x2110719174FA3473ULL) + aTwistOrbiterAssignSaltE[((aIndex + 29U)) & S_SALT1];
            aOrbiterE = (aWandererI + RotL64(aCross, 37U)) + 0xB0FE0FC8BA10BB72ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aIngress, 10U)) + 0x0E353DE9C203CF15ULL) + aTwistOrbiterAssignSaltB[((aIndex + 21U)) & S_SALT1];
            aOrbiterD = ((aWandererF + RotL64(aCross, 43U)) + RotL64(aCarry, 19U)) + 0xA4635D6F2354E7A7ULL;
            aOrbiterF = ((aWandererB + RotL64(aScatter, 5U)) + RotL64(aCarry, 27U)) + 0xCE94AB360D40740EULL;
            aOrbiterG = (aWandererD + RotL64(aPrevious, 53U)) + 0xA6FB484307949260ULL;
            aOrbiterC = (aWandererE + RotL64(aIngress, 48U)) + 0x63F9CE1E7D0114E3ULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterA) + 0x903C85509FC6B374ULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterI) ^ 0xF820B647365D3C8EULL) ^ aTwistOrbiterUpdateSaltC[(((31U - aIndex) + 14U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xCEDD8E0D59680D8BULL), 57U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterH) + 0xD62724F4CC49E1B7ULL) + aTwistOrbiterUpdateSaltD[(((31U - aIndex) + 3U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x1BD53E8C3A86CDEEULL;
