            aOrbiterG = (((aWandererB + RotL64(aPrevious, 29U)) + RotL64(aCarry, 57U)) + 0xC57C253F85C5152CULL) + aKeyRotateOrbiterAssignSaltD[(((31U - aIndex) + 22U)) & S_SALT1];
