            aOrbiterE = (aOrbiterE + aOrbiterA) + 0x5662EB0A8CD5C5B8ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterE) ^ 0x2F958BEBAA4BB498ULL) ^ aKeyRotateOrbiterUpdateSaltF[(((31U - aIndex) + 11U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x4ECC92E19E79485DULL), 3U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterI) + 0x808BB7CA2056895CULL;
            aOrbiterB = (aOrbiterB ^ aOrbiterD) ^ 0x6AE72D032BE540EBULL;
            aOrbiterB = RotL64((aOrbiterB * 0xAEC9EA3B7030C757ULL), 29U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterB) + 0x5272B1A5BDE73B69ULL) + aKeyRotateOrbiterUpdateSaltA[((aIndex + 19U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterJ) ^ 0xFDB26DA9ABC67D65ULL;
            aOrbiterK = RotL64((aOrbiterK * 0x6FE875149495DA7DULL), 43U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterG) + 0x5CBB58F54425AE54ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0xCBB9D9037DFAD072ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x7DF822A5B43869F7ULL), 53U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0xE1B93D6D1BB1DFA7ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x36D9240AC6B9AF64ULL;
            aOrbiterH = RotL64((aOrbiterH * 0x0C393B6EDA9F7663ULL), 21U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterJ) + 0x5714383AA7A682EDULL) + aKeyRotateOrbiterUpdateSaltB[((aIndex + 10U)) & S_SALT1];
