            aOrbiterA = ((aOrbiterA + aOrbiterI) + 0x8682339B9D160ABDULL) + aKeyRotateOrbiterUpdateSaltD[((aIndex + 25U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterA) ^ 0xEC9BD0D02E310868ULL;
