            aOrbiterH = ((aOrbiterH ^ aOrbiterC) ^ 0xD1CC8FDD2CB72367ULL) ^ aKeySpawnOrbiterUpdateSaltB[(((31U - aIndex) + 19U)) & S_SALT1];
