            aIngress = (RotL64(aFuseLaneA[((aIndex + 11750U)) & S_BLOCK1], 29U) ^ RotL64(aCelestialLaneC[((aIndex + 13792U)) & S_BLOCK1], 51U));
            aIngress ^= (RotL64(aAetherLaneA[((aIndex + 13943U)) & S_BLOCK1], 4U) ^ RotL64(aVaporLaneC[((S_BLOCK1 - aIndex + 14831U)) & S_BLOCK1], 43U));
            aIngress = TwistMix64::DiffuseB(aIngress);
