            aOrbiterJ = (aOrbiterJ + aOrbiterD) + 0xCB07B3ABA86E78CFULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0x74B29CEAD763B95AULL) ^ aKeySpawnOrbiterUpdateSaltF[(((31U - aIndex) + 9U)) & S_SALT1];
